import{n as e}from"./QTnfLwEv.js";var t=e({default:()=>n}),n={"faq.answer.hostinger-pro-a1":`<p>Agency hosting is web hosting service tailored specifically for web developers, freelancers, and agencies who look after multiple client websites to efficiently manage various sites under one account, via one easy-to-use dashboard. Alongside managing multiple websites from one place, Hostinger Pro offers optimal performance, full security, the ability to scale your business and 24/7 expert support.</p>`,"faq.answer.hostinger-pro-a2":`<p>Cloud plans offer a dedicated IP address together with dedicated resources from a network of servers to ensure maximum performance and uptime. With these plans, you can get 4x more speed and total control of servers’ resources to maximise their potential.</p><p>Hostinger uses CloudLinux with LVE containers. In this setup, each user gets a container with resource boundaries to maintain smooth operation.</p><p>This means that the resources you get are comparable to a virtual private server (VPS). But unlike VPS, you don’t need technical expertise to set up and manage cloud hosting – it’s as easy as using <a href='https://www.hostinger.com/in/web-hosting'>managed web hosting</a>.</p><p>Once your website needs more resources, you can upgrade from web hosting to cloud hosting directly via the Members Area with just a few clicks.</p>`,"faq.answer.hostinger-pro-a3":`<p>Refer your clients to Hostinger and earn a commission every time they sign up for one of our annual plans – equivalent to 20% of the plan’s price. Plus, your referred clients earn a 20% discount too. Win-win.</p><p>And, because the number of referrals is unlimited, so is your earning potential.</p>`,"faq.answer.hostinger-pro-a5":`<p>Once you add a client, they will need to verify your access request. Then, you will be able to manage their services and websites directly from your hPanel.</p><p>This is a great solution when it comes to agencies and freelancers that have many clients – no more switching between different hosting control panels and dashboards.</p>`,"faq.answer.hostinger-pro-a6":`<p>You have full ownership and access to your client’s account – depending on the access level and services chosen. That means you do not have to manually log in to their account to manage their websites and services.</p>`,"faq.answer.hostinger-pro-a7":`<p>Hostinger Referral program is free to join. Simply <a href='{link}'>sign up</a> to create your free account and begin adding clients.</p>`,"faq.answer.hostinger-pro-a8":`<p>Hostinger offers priority support with all cloud plans. Our Customer Success team has highly skilled professionals available 24/7.</p><p>We’re ready to answer any question you may have, including but not limited to selecting hosting plans, and setting up services, as well as technical topics related to WordPress, website troubleshooting, migrations, and backups.</p>`,"faq.answer.hostinger-pro-a9":`<p>Hostinger offers priority support with all cloud plans. Our Customer Success team consists of highly skilled professionals available 24/7 – we will get back to you in less than one minute. </p><p>We’re ready to answer general questions about our hosting plans and technical topics related to WordPress, migrations, and backups.</p>`,"faq.question.hostinger-pro-q6":`What kind of access will I have?`,"faq.answer.hostinger-pro-a4":`<p>The sky's the limit – Using our Access Sharing feature, add as many clients as you want to the hPanel.</p>`,"faq.answer.hostinger-pro-a10":`<p>Yes, you can quickly and easily migrate your existing website to Hostinger - and it’s free. We offer an unlimited website migrations service that handles everything and ensures you can transfer your site - or sites - without any hassle, cost, data loss, or downtime.</p>`,"faq.question.hostinger-pro-q1":`What is agency web hosting?`,"faq.question.hostinger-pro-q2":`Why should I choose cloud hosting?`,"faq.question.hostinger-pro-q3":`How much can I earn from the referral program?`,"faq.question.hostinger-pro-q4":`How many customers can I manage with Hostinger?`,"faq.question.hostinger-pro-q5":`How can I get access to my clients’ sites?`,"faq.question.hostinger-pro-q7":`How much does it cost to join the referral program?`,"faq.question.hostinger-pro-q8":`What kind of support can I expect?`,"faq.question.hostinger-pro-q9":`Can I share access to specific website hosted on my Agency plan?`,"faq.question.hostinger-pro-q10":`Can I migrate existing websites to Hostinger?`};export{t as n,n as t};